def get_conn():
    print("checkout")
    try:
        yield "conn"
        print("commit")
    except ValueError:
        print("rollback")
        raise
    finally:
        print("return to pool")

def handler(conn):
    print("handler uses", conn)
    raise ValueError("bad row")

gen = get_conn()
conn = next(gen)
try:
    handler(conn)
except ValueError as e:
    try:
        gen.throw(e)
    except ValueError:
        print("500 sent")
